<?php require 'functions.php';$id=(int)($_GET['id']??0);$stmt=$conn->prepare('SELECT i.*,u.name,u.email FROM items i JOIN users u ON u.id=i.user_id WHERE i.id=?');$stmt->bind_param('i',$id);$stmt->execute();$item=$stmt->get_result()->fetch_assoc();if(!$item){flash('error','Listing not found.');redirect('browse.php');}$page_title=$item['title'];require 'header.php'; ?>
<div class="row g-4"><div class="col-lg-7"><?php if($item['image']):?><img src="uploads/<?=e($item['image'])?>" class="w-100 rounded-4 shadow-sm" style="max-height:520px;object-fit:cover" alt="<?=e($item['title'])?>"><?php else:?><div class="placeholder-photo rounded-4" style="height:400px"><i class="bi bi-box-seam"></i></div><?php endif;?></div><div class="col-lg-5"><span class="badge badge-<?=e($item['status'])?> text-capitalize mb-3"><?=e($item['status'])?></span><h1 class="display-6 fw-bold"><?=e($item['title'])?></h1><p class="text-secondary"><i class="bi bi-tag"></i> <?=e($item['category'])?> &nbsp; <i class="bi bi-calendar3"></i> <?=date('M j, Y',strtotime($item['item_date']))?></p><hr><p><i class="bi bi-geo-alt-fill text-primary"></i> <strong><?=e($item['location'])?></strong></p><p class="text-secondary" style="white-space:pre-line"><?=e($item['description'])?></p><p class="small text-secondary">Posted by <?=e($item['name'])?> · <?=date('M j',strtotime($item['created_at']))?></p>
<?php if(logged_in() && $_SESSION['user']['id'] != $item['user_id'] && $item['status']!='returned'):?><a href="claim.php?id=<?=$item['id']?>" class="btn btn-primary w-100"><i class="bi bi-hand-index-thumb"></i> This may be mine</a><?php elseif(!logged_in()):?><a href="login.php" class="btn btn-primary w-100">Sign in to claim</a><?php elseif($_SESSION['user']['id']==$item['user_id']):?><a href="my-items.php" class="btn btn-outline-primary w-100">Manage this listing</a><?php endif;?></div></div><?php require 'footer.php'; ?>
